"""Keysight ADS backend (adapter) based on the Python API bundled with ADS.

Two ways to use it on a machine with ADS:

* ``ADSBackend()`` - simulate netlists generated by AnalogForge from the
  neutral circuit (needs an ADS-capable PDK profile; syntax unvalidated);
* ``ADSBackend(workspace=..., cellview=(lib, cell, view))`` - ADS netlists the
  existing schematic itself and AnalogForge only substitutes the design
  variables (recommended: device models, layout-aware components and
  OscPorts are whatever you placed in ADS).

See docs/keysight_ads.md.  Not executed in the development environment.
"""

from __future__ import annotations

import shutil
import tempfile
import time
from pathlib import Path

import numpy as np

from ...core.pdk import PDK
from ...core.results import Dataset, SimResult
from ...core.testbench import Testbench
from ..base import Backend, register_backend
from . import api
from .netlist import ads_name, render_netlist, substitute_variables

_KIND_HINTS = {"op": ("dc",), "dc": ("dc",), "ac": ("ac",), "tran": ("tran",), "noise": ("ac", "noise"),
               "pss": ("hb",), "pnoise": ("hb", "pnoise")}


def _signal_name(col: str) -> str:
    low = col.lower()
    if low.endswith(".i"):
        return f"i({low[:-2]})"
    if low in ("freq", "time"):
        return low
    return low if "(" in low else f"v({low})"


def blocks_to_datasets(blocks: dict[str, dict], tb: Testbench) -> dict[str, Dataset]:
    """Assign ADS dataset blocks to the testbench analyses (by controller name, then by kind)."""
    out: dict[str, Dataset] = {}
    used: set[str] = set()
    for an in tb.analyses:
        ctrl = ads_name(f"AF_{an.key()}").lower()
        match = next((b for b in blocks if ctrl in b.lower() and b not in used), None)
        if match is None:
            hints = _KIND_HINTS.get(an.kind, ())
            match = next((b for b in blocks if b not in used and any(h in b.lower() for h in hints)), None)
        if match is None:
            continue
        used.add(match)
        blk = blocks[match]
        sig = {_signal_name(k): np.asarray(v) for k, v in blk["signals"].items()}
        x = np.real(np.asarray(blk["x"], dtype=complex)) if len(blk["x"]) else np.zeros(1)
        out[an.key()] = Dataset(an.kind, blk["x_name"].lower(), x, sig)
    return out


@register_backend
class ADSBackend(Backend):
    name = "ads"
    capabilities = frozenset({"op", "dc", "ac", "tran", "noise", "pss", "pnoise"})
    verification = "adapter: unit-tested against a fake keysight API; not executed with a real ADS installation"
    netlist_suffix = "net"

    def __init__(self, workspace: str | None = None, cellview: tuple[str, str, str] | None = None,
                 keep_files: bool = False):
        self.workspace = workspace
        self.cellview = cellview
        self.keep_files = keep_files

    def available(self) -> tuple[bool, str]:
        return api.api_available()

    def version(self) -> str | None:
        try:
            import keysight  # type: ignore
            return getattr(keysight, "__version__", "ADS")
        except ImportError:
            return None

    def netlist(self, tb: Testbench, pdk: PDK) -> str:
        self.check_supported(tb)
        if self.cellview and self.workspace:
            base = api.netlist_from_schematic(self.workspace, *self.cellview)
            return substitute_variables(base, tb.variables)
        return render_netlist(tb, pdk)

    def run(self, tb: Testbench, pdk: PDK) -> SimResult:
        res = SimResult(backend=self.name)
        ok, why = self.available()
        if not ok:
            res.error = why
            try:
                res.netlist = render_netlist(tb, pdk)
            except Exception:
                pass
            return res
        workdir = Path(tempfile.mkdtemp(prefix="afads_"))
        t0 = time.perf_counter()
        try:
            res.netlist = self.netlist(tb, pdk)
            (workdir / f"{tb.name}.net").write_text(res.netlist)
            files = api.run_netlist(res.netlist, workdir)
            blocks: dict[str, dict] = {}
            for f in files:
                blocks.update(api.read_dataset(f))
            res.datasets = blocks_to_datasets(blocks, tb)
            missing = [a.key() for a in tb.analyses if a.key() not in res.datasets]
            res.ok = not missing
            if missing:
                res.error = f"ADS produced no data for {missing} (dataset blocks: {list(blocks)})"
            res.version = self.version()
        except Exception as exc:
            res.error = f"{type(exc).__name__}: {exc}"
        finally:
            res.elapsed_s = time.perf_counter() - t0
            if not self.keep_files:
                shutil.rmtree(workdir, ignore_errors=True)
        return res


__all__ = ["ADSBackend", "render_netlist", "substitute_variables", "blocks_to_datasets"]
